function generate(rand, size) {
  const large = size === 'large';
  const alphabets = ['ab', 'abc', 'abcd', 'aAbB', 'xyzXYZ'];
  const letters = large ? 'abcde' : alphabets[Math.floor(rand() * alphabets.length)];
  const length = large ? 10000 : 1 + Math.floor(rand() * 10);
  let s = '';
  // Build the string from runs so long two-letter stretches appear.
  while (s.length < length) {
    const letter = letters[Math.floor(rand() * letters.length)];
    const run = 1 + Math.floor(rand() * (large ? 40 : 3));
    s += letter.repeat(run);
  }
  return [s.slice(0, length)];
}
